class Passage {
  final String id;
  final String title;
  final String language;
  final String category;
  final String text;
  final int? keystrokeTarget;

  const Passage({
    required this.id,
    required this.title,
    required this.language,
    required this.category,
    required this.text,
    this.keystrokeTarget,
  });
}

